{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    by_symbol = {}
    for node in nodes:
        by_symbol.setdefault(node.get("symbol"), []).append(node)

    removed = []
    retained = []
    for node in nodes:
        if node.get("removable"):
            utility = node.get("utility")
            has_competitor = any(
                other is not node
                and other.get("symbol") == node.get("symbol")
                and other.get("utility") is not None
                and utility is not None
                and other.get("utility") >= utility
                for other in by_symbol.get(node.get("symbol"), [])
            )
            if has_competitor:
                removed.append(node.get("id"))
                continue
        retained.append(node.get("id"))

    return {
        "removed_node_ids": removed,
        "retained_node_ids": retained,
    }"}
